import re
from collections import Counter
def names(doc):
    return re.findall(r"\b([A-Z][a-z]+(?:[A-Z][a-z]+)+)\b", doc)
cnt = Counter()
per_doc = []
for d in docs:
    c = Counter(names(d))
    per_doc.append(c)
    for k,v in c.items():
        cnt[k]+=v
common = {k:v for k,v in cnt.items() if all(k in pd for pd in per_doc)}
print("common count:", len(common))
for k,v in sorted(common.items(), key=lambda x:-x[1])[:50]:
    print(v,k)
